nt table setup in Kayonza","description":"asset listing in Kayonza. Confirm the exact item or service, condition, included accessories, and availability with the owner.","price":195000,"district":"Kayonza","transaction_type":"rent_out","images":["/properties/other-04.jpg","/properties/other-05.jpg","/properties/other-demo-06.jpg","/properties/other-02.jpg","/properties/other-03.jpg"],"bedrooms":0,"bathrooms":0,"area":0},{"fixture_id":"test-other-9","category":"other","title":"Restaurant fixtures in Nyamata","description":"asset listing in Nyamata. Confirm the exact item or service, condition, included accessories, and availability with the owner.","price":215000,"district":"Nyamata","transaction_type":"sell","images":["/properties/other-05.jpg","/properties/other-demo-06.jpg","/properties/other-02.jpg","/properties/other-03.jpg","/properties/other-04.jpg"],"bedrooms":0,"bathrooms":0,"area":0},{"fixture_id":"test-other-10","category":"other","title":"City bicycle in Karongi","description":"asset listing in Karongi. Confirm the exact item or service, condition, included accessories, and availability with the owner.","price":235000,"district":"Karongi","transaction_type":"rent_out","images":["/properties/other-demo-06.jpg","/properties/other-02.jpg","/properties/other-03.jpg","/properties/other-04.jpg","/properties/other-05.jpg"],"bedrooms":0,"bathrooms":0,"area":0}]$fixtures$::jsonb)
    AS f(fixture_id text, category text, title text, description text, price numeric,
         district text, transaction_type text, images jsonb, bedrooms integer,
         bathrooms integer, area numeric)
), inserted AS (
    INSERT INTO listings (owner_id, category, transaction_type, title, description, price,
                          currency, province, district, sector, status, tags, contact_method)
    SELECT '00000000-0000-4000-8000-00000000d001', f.category, f.transaction_type,
           f.title, f.description, f.price, 'RWF', 'Rwanda', f.district, '',
           'published', jsonb_build_array('public-demo', 'umutungo-fixture:' || f.fixture_id), 'message'
    FROM fixtures f
    WHERE NOT EXISTS (
        SELECT 1 FROM listings l
        WHERE l.owner_id = '00000000-0000-4000-8000-00000000d001'
          AND l.tags @> jsonb_build_array('umutungo-fixture:' || f.fixture_id)
          AND l.deleted_at IS NULL
    )
    RETURNING id, tags
)
INSERT INTO listing_media (listing_id, media_type, url, sort_order)
SELECT l.id, 'photo', image.url, image.ordinality::integer - 1
FROM listings l
JOIN fixtures f ON l.tags @> jsonb_build_array('umutungo-fixture:' || f.fixture_id)
CROSS JOIN LATERAL jsonb_array_elements_text(f.images) WITH ORDINALITY AS image(url, ordinality)
WHERE l.owner_id = '00000000-0000-4000-8000-00000000d001'
  AND NOT EXISTS (SELECT 1 FROM listing_media m WHERE m.listing_id = l.id);

