INSERT INTO measurements (listing_id, building_size, land_size, bedrooms, bathrooms)
SELECT l.id, NULLIF(f.area, 0), NULLIF(f.area, 0), NULLIF(f.bedrooms, 0), NULLIF(f.bathrooms, 0)
FROM fixtures f
JOIN listings l ON l.owner_id = '00000000-0000-4000-8000-00000000d001'
  AND l.tags @> jsonb_build_array('umutungo-fixture:' || f.fixture_id)
WHERE (f.area > 0 OR f.bedrooms > 0 OR f.bathrooms > 0)
  AND NOT EXISTS (SELECT 1 FROM measurements m WHERE m.listing_id = l.id);
